function solve({config,state,event}){
 const M=config.maxBytes;
 if(!state)state={v:{},t:null,b:[],d:false,e:0};
 const bad=()=>{state.e++;state.t=null};
 const scalar=x=>x===null||typeof x==='string'||typeof x==='boolean'||(typeof x==='number'&&Number.isSafeInteger(x));
 const keys=(o,a)=>{if(!o||typeof o!=='object'||Array.isArray(o))return false;let k=Object.keys(o).sort();return k.length===a.length&&a.every(x=>k.includes(x))};
 const frame=a=>{let s;try{s=new TextDecoder('utf-8',{fatal:true}).decode(new Uint8Array(a))}catch(_){bad();return}let o;try{o=JSON.parse(s)}catch(_){bad();return}
  let ok=false;
  if(keys(o,['op','id'])&&o.op==='begin'&&typeof o.id==='string')ok=true;
  else if(keys(o,['op','key','value'])&&o.op==='put'&&typeof o.key==='string'&&scalar(o.value))ok=true;
  else if(keys(o,['op','id'])&&o.op==='commit'&&typeof o.id==='string')ok=true;
  else if(keys(o,['op'])&&o.op==='abort')ok=true;
  if(!ok){bad();return}
  if(o.op==='begin'){if(state.t)bad();else state.t={id:o.id,d:Object.assign({},state.v)}}
  else if(o.op==='put'){if(!state.t)bad();else state.t.d[o.key]=o.value}
  else if(o.op==='commit'){if(!state.t||state.t.id!==o.id)bad();else{state.v=state.t.d;state.t=null}}
  else state.t=null;
 };
 const add=n=>{for(let i=0;i<n;i++){let x=event.bytes[i];if(state.d){if(x===10)state.d=false;continue}if(x===10){frame(state.b);state.b=[]}else{state.b.push(x);if(state.b.length>M){state.e++;state.t=null;state.b=[];state.d=true}}}};
 if(event.type==='chunk')add(event.bytes);else if(event.type==='finish'){if(state.d)state.d=false;else if(state.b.length){state.e++;state.b=[]}if(state.t){state.e++;state.t=null}}else bad();
 return {state:state,output:{visible:state.v,open:state.t?state.t.id:null,buffered:state.b.length,errors:state.e}};
}
